using System;using System.IO;using System.IO.Compression;using System.Linq;using System.Text;using BeamScheduleFormatter;
class BeamDeflectionTests {
 static int checks;static void Check(bool ok,string why){checks++;if(!ok)throw new Exception(why);}static void Near(double a,double b,string why,double tol=1e-6){Check(Math.Abs(a-b)<tol,why+" (got "+a+", expected "+b+")");}
 static void Throws(Action action,string contains,string why){try{action();}catch(Exception ex){Check(ex.Message.IndexOf(contains,StringComparison.OrdinalIgnoreCase)>=0,why+" - message was: "+ex.Message);return;}throw new Exception("Expected failure: "+why);}
 const string Nodes="Node\tX (m)\tY (m)\tZ (m)\r\n1\t0\t3\t0\r\n2\t2\t3\t0\r\n3\t4\t3\t0\r\n4\t6\t3\t0\r\n5\t0\t0\t0\r\n6\t6\t0\t0\r\n7\t8\t3\t0";
 const string Beams="Beam\tNode A\tNode B\tLength (m)\tProperty\r\n1\t1\t2\t2\t1\r\n2\t2\t3\t2\t1\r\n3\t3\t4\t2\t1\r\n4\t5\t1\t3\t2\r\n5\t6\t4\t3\t2\r\n6\t4\t7\t2\t1";
 // Supports settle 1 mm (A) and 3 mm (B); interior nodes sag. Units in mm from the heading.
 const string Disp="Node\tL/C\tX (mm)\tY (mm)\tZ (mm)\tResultant (mm)\trX (rad)\trY (rad)\trZ (rad)\r\n1\t1 DEAD\t0\t-1\t0\t1\t0\t0\t0.001\r\n\t2 LIVE\t0\t-0.5\t0\t0.5\t0\t0\t0\r\n2\t1 DEAD\t0.1\t-9\t0\t9\t0\t0\t0\r\n\t2 LIVE\t0\t-4\t0\t4\t0\t0\t0\r\n3\t1 DEAD\t0.1\t-12\t0\t12\t0\t0\t0\r\n\t2 LIVE\t0\t-6\t0\t6\t0\t0\t0\r\n4\t1 DEAD\t0\t-3\t0\t3\t0\t0\t0\r\n\t2 LIVE\t0\t-1\t0\t1\t0\t0\t0\r\n7\t1 DEAD\t0\t-10\t0\t10\t0\t0\t0\r\n\t2 LIVE\t0\t-4\t0\t4\t0\t0\t0";
 static BeamDeflectionData Data(){var d=new BeamDeflectionData();StaadDisplacements.Coordinates(d,Nodes,"mm");StaadDisplacements.Members(d,Beams);StaadDisplacements.Displacements(d,Disp,"m");return d;}
 static void Main(){
  var d=Data();Check(d.Nodes.Count==7&&d.Members.Count==6,"tables read");Check(d.GeometryUnitSource.Contains("header (m)"),"geometry unit from header overrides selected mm");Check(d.DisplacementUnitSource.Contains("header (mm)"),"displacement unit from header overrides selected m");Near(d.Nodes[4].X,6,"metres kept");Near(d.Displacements.First(x=>x.Node==3&&x.Case=="1 DEAD").Y,-0.012,"mm converted to m");Check(d.Cases().Count()==2,"two load cases with blank node continuation rows");
  var input=new PhysicalBeamInput{Name="B1",Members="1, 2, 3",LimitRatio=360,Vertical="Y",ServiceBasis=true,SupportsVerified=true};var r=BeamDeflection.Calculate(d,input);Check(r.Count==2,"all cases when blank");var dead=r.First(x=>x.Case=="1 DEAD");
  Near(dead.Span,6,"span across three members");Check(dead.Stations.Select(s=>s.Node).SequenceEqual(new[]{1,2,3,4}),"ordered path through intermediate nodes");
  // Chord at node 2: -1 + (-3 - -1)*2/6 = -1.6667; relative = -9 + 1.6667 = -7.3333. Node 3: chord -2.3333, relative -9.6667.
  Near(dead.Stations[1].Relative,-9+1+2.0/3,"node 2 relative to chord");Near(dead.Stations[2].Relative,-12+1+4.0/3,"node 3 relative to chord");Near(dead.MaximumMm,9.6666666667,"governing magnitude",1e-6);Check(dead.GoverningNode==3,"governing node");Near(dead.At,4,"governing station");Near(dead.LimitMm,6000/360.0,"L/360");Check(!dead.Exceeds&&dead.Qualified&&dead.Status.StartsWith("OK"),"within limit and confirmed");Near(dead.Stations[0].Relative,0,"support A zero");Near(dead.Stations[3].Relative,0,"support B zero");Check(dead.Ratio=="L/620","L/δ text "+dead.Ratio);
  input.Members="3 2 1";input.Start=4;r=BeamDeflection.Calculate(d,input);Check(r[0].StartNode==4&&r[0].Stations[1].Node==3,"explicit support A reverses path");input.Start=0;
  input.Members="1-3";input.Cases="2";r=BeamDeflection.Calculate(d,input);Check(r.Count==1&&r[0].Case=="2 LIVE","case selected by number and member range");
  input.LimitRatio=2000;r=BeamDeflection.Calculate(d,input);Check(r[0].Exceeds&&r[0].Status.StartsWith("EXCEEDS"),"tight limit exceeds");input.LimitRatio=360;
  input.AbsoluteLimitMm=3;r=BeamDeflection.Calculate(d,input);Near(r[0].LimitMm,3,"absolute limit governs when smaller");input.AbsoluteLimitMm=0;
  input.ServiceBasis=false;r=BeamDeflection.Calculate(d,input);Check(!r[0].Qualified&&r[0].Status.Contains("service"),"unconfirmed load basis is REVIEW, not OK");input.ServiceBasis=true;input.SupportsVerified=false;r=BeamDeflection.Calculate(d,input);Check(!r[0].Qualified&&r[0].Status.Contains("supports"),"unconfirmed supports is REVIEW");input.SupportsVerified=true;
  // Cantilever from node 4 to 7: relative to support translation only.
  var cant=new PhysicalBeamInput{Name="C1",Members="6",SpanType=BeamDeflection.Cantilever,Start=4,LimitRatio=180,Vertical="Y",ServiceBasis=true,SupportsVerified=true,Cases="1"};r=BeamDeflection.Calculate(d,cant);Near(r[0].MaximumMm,7,"cantilever tip relative to root");Near(r[0].LimitMm,2000/180.0,"cantilever limit");Check(r[0].Qualified,"cantilever OK");
  var single=new PhysicalBeamInput{Name="S",Members="6",LimitRatio=360,Vertical="Y",ServiceBasis=true,SupportsVerified=true};r=BeamDeflection.Calculate(d,single);Check(r[0].Status.StartsWith("NOT CHECKED")&&!r[0].Qualified,"no interior node between supports is not checked");
  Throws(()=>BeamDeflection.Calculate(d,new PhysicalBeamInput{Name="X",Members="1,2,3",LimitRatio=360,Vertical="X"}),"along the beam","axial component rejected");
  Throws(()=>BeamDeflection.Calculate(d,new PhysicalBeamInput{Name="X",Members="1,4",LimitRatio=360,Vertical="Y"}),"straight","non-collinear rejected");
  Throws(()=>BeamDeflection.Calculate(d,new PhysicalBeamInput{Name="X",Members="1,3",LimitRatio=360,Vertical="Y"}),"connected","gap rejected");
  Throws(()=>BeamDeflection.Calculate(d,new PhysicalBeamInput{Name="X",Members="1,2,3",LimitRatio=360,Vertical="Y",Cases="9"}),"not in the displacement","absent case rejected");
  Throws(()=>BeamDeflection.Calculate(d,new PhysicalBeamInput{Name="X",Members="1,2,3",LimitRatio=360,Vertical="Y",Start=2}),"not an end node","interior support rejected");
  Throws(()=>BeamDeflection.Calculate(d,new PhysicalBeamInput{Name="X",Members="1,1",LimitRatio=360,Vertical="Y"}),"twice","duplicate member rejected");
  Throws(()=>BeamDeflection.Calculate(d,new PhysicalBeamInput{Name="X",Members="1,2,3",LimitRatio=0,Vertical="Y"}),"positive","zero limit rejected");
  var missing=new BeamDeflectionData();StaadDisplacements.Coordinates(missing,Nodes,"m");StaadDisplacements.Members(missing,Beams);StaadDisplacements.Displacements(missing,"Node\tL/C\tX\tY\tZ\r\n1\t1\t0\t0\t0\r\n4\t1\t0\t0\t0","mm");Throws(()=>BeamDeflection.Calculate(missing,new PhysicalBeamInput{Name="M",Members="1,2,3",LimitRatio=360,Vertical="Y"}),"no displacement for node(s) 2, 3","missing intermediate node named");Check(missing.DisplacementUnitSource.Contains("selected unit (mm)"),"selected unit used without header units");
  Throws(()=>StaadDisplacements.Displacements(new BeamDeflectionData(),"Node\tL/C\tX (mm)\tY (m)\tZ (mm)\r\n1\t1\t0\t0\t0","mm"),"mix","mixed header units rejected");
  Throws(()=>StaadDisplacements.Displacements(new BeamDeflectionData(),"Node\tL/C\tX\tY\tZ\r\n1\t1\t0\t1,5\t0","mm"),"Invalid number","comma decimal rejected");
  var unitRow=new BeamDeflectionData();StaadDisplacements.Displacements(unitRow,"Node,L/C,X,Y,Z\r\n,,cm,cm,cm\r\n5,\"1 DL, roof\",0,-2.5,0","mm");Near(unitRow.Displacements[0].Y,-0.025,"separate unit row and quoted CSV case");Check(unitRow.Displacements[0].Case=="1 DL, roof","quoted case name kept");
  Throws(()=>{var c=new BeamDeflectionData();StaadDisplacements.Coordinates(c,"Node\tX\tY\tZ\r\n1\t0\t0\t0\r\n1\t1\t0\t0","m");},"Conflicting","conflicting node rejected");
  // STD model: UNIT MMS, continuation, semicolons, SET Z UP, supports with TO.
  string std="STAAD SPACE\r\nSTART JOB INFORMATION\r\nEND JOB INFORMATION\r\nSET Z UP\r\nUNIT MMS KN\r\nJOINT COORDINATES\r\n1 0 0 3000; 2 2000 0 3000; 3 4000 0 3000; -\r\n4 6000 0 3000;\r\n5 0 0 0; 6 6000 0 0;\r\nMEMBER INCIDENCES\r\n1 1 2; 2 2 3; 3 3 4; 4 5 1; 5 6 4;\r\nDEFINE MATERIAL START\r\nEND DEFINE MATERIAL\r\nSUPPORTS\r\n5 TO 6 FIXED\r\nFINISH\r\n";
  var model=new BeamDeflectionData();var supports=new System.Collections.Generic.HashSet<int>();StaadDisplacements.Model(model,std,"m",supports);Check(model.Nodes.Count==6&&model.Members.Count==5&&model.ZUp,"STD geometry read with continuation");Near(model.Nodes[4].X,6,"MMS converted to metres");Near(model.Nodes[1].Z,3,"Z up coordinate");Check(supports.SetEquals(new[]{5,6}),"supports TO range");Check(model.GeometryUnitSource.Contains("UNIT command (mm)"),"unit from STAAD UNIT");
  Throws(()=>StaadDisplacements.Model(new BeamDeflectionData(),"UNIT METER KN\r\nJOINT COORDINATES\r\n1 0 0 0; 2 5 0 0;\r\nREPEAT 3 0 3 0\r\n","m"),"REPEAT","REPEAT geometry rejected with guidance");
  var groups=BeamDeflection.SuggestGroups(model,"Z");Check(groups.Count==1&&groups[0].Value.OrderBy(x=>x).SequenceEqual(new[]{1,2,3}),"suggested beam line split at columns");
  var frame=Data();var lines=BeamDeflection.SuggestGroups(frame,"Y");Check(lines.Count==1&&lines[0].Value.OrderBy(x=>x).SequenceEqual(new[]{1,2,3}),"column at node 4 ends the beam line before cantilever member 6");
  // ANL: input echo with unit, page break, continuation rows, and CM heading.
  string anl="    1. STAAD SPACE\r\n    2. UNIT METER KN\r\n    3. JOINT COORDINATES\r\n    4. 1 0 3 0; 2 2 3 0; 3 4 3 0; 4 6 3 0\r\n    5. MEMBER INCIDENCES\r\n    6. 1 1 2; 2 2 3; 3 3 4\r\n    7. PRINT JOINT DISPLACEMENTS LIST 1 TO 4\r\n\r\n   JOINT DISPLACEMENT (CM   RADIANS)    STRUCTURE TYPE = SPACE\r\n   ------------------\r\n\r\n  JOINT  LOAD   X-TRANS   Y-TRANS   Z-TRANS   X-ROTAN   Y-ROTAN   Z-ROTAN\r\n\r\n      1    1    0.00000  -0.10000   0.00000   0.00000   0.00000   0.00010\r\n           2    0.00000  -0.05000   0.00000   0.00000   0.00000   0.00000\r\n      2    1    0.01000  -0.90000   0.00000   0.00000   0.00000   0.00000\r\n           2    0.00000  -0.40000   0.00000   0.00000   0.00000   0.00000\r\n STAAD SPACE                                              -- PAGE NO.    5\r\n      3    1    0.01000  -1.20000   0.00000   0.00000   0.00000   0.00000\r\n           2    0.00000  -0.60000   0.00000   0.00000   0.00000   0.00000\r\n      4    1    0.00000  -0.30000   0.00000   0.00000   0.00000   0.00000\r\n           2    0.00000  -0.10000   0.00000   0.00000   0.00000   0.00000\r\n\r\n ************** END OF LATEST ANALYSIS RESULT **************\r\n      9    1    9.0 9.0 9.0 9.0 9.0 9.0\r\n";
  var a=new BeamDeflectionData();StaadDisplacements.Anl(a,anl,"m","mm");Check(a.Nodes.Count==4&&a.Members.Count==3,"geometry from ANL echo");Check(a.Displacements.Count==8,"8 displacement rows; rows after END ignored and PRINT echo not a table");Near(a.Displacements.First(x=>x.Node==3&&x.Case=="1").Y,-0.012,"CM heading converted");Check(a.DisplacementUnitSource.Contains("heading (cm)"),"ANL unit source");
  r=BeamDeflection.Calculate(a,new PhysicalBeamInput{Name="B1",Members="1,2,3",Cases="1",LimitRatio=360,Vertical="Y",ServiceBasis=true,SupportsVerified=true});Near(r[0].MaximumMm,9.6666666667,"ANL and table give the same result",1e-6);
  Throws(()=>StaadDisplacements.Anl(new BeamDeflectionData(),"no tables here","m","mm"),"PRINT JOINT DISPLACEMENTS","ANL without table gives STAAD guidance");
  // Excel import reads cached cells of each worksheet.
  string xlsx=Path.Combine(Path.GetTempPath(),"deflection-test-"+Guid.NewGuid().ToString("N")+".xlsx");try{using(var stream=File.Create(xlsx))using(var zip=new ZipArchive(stream,ZipArchiveMode.Create)){Action<string,string> add=(name,text)=>{using(var w=new StreamWriter(zip.CreateEntry(name).Open(),new UTF8Encoding(false)))w.Write(text);};add("xl/sharedStrings.xml","<sst xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><si><t>Node</t></si><si><t>L/C</t></si><si><t>X mm</t></si><si><t>Y mm</t></si><si><t>Z mm</t></si><si><t>1 DL</t></si></sst>");add("xl/worksheets/sheet1.xml","<worksheet xmlns='http://schemas.openxmlformats.org/spreadsheetml/2006/main'><sheetData><row r='1'><c r='A1' t='s'><v>0</v></c><c r='B1' t='s'><v>1</v></c><c r='C1' t='s'><v>2</v></c><c r='D1' t='s'><v>3</v></c><c r='E1' t='s'><v>4</v></c></row><row r='2'><c r='A2'><v>2</v></c><c r='B2' t='s'><v>5</v></c><c r='C2'><v>0</v></c><c r='D2'><v>-7.5</v></c><c r='E2'><v>0</v></c></row></sheetData></worksheet>");}
   var tables=StaadSpreadsheet.Tables(xlsx);var x=new BeamDeflectionData();StaadDisplacements.Displacements(x,tables.Values.First(),"m");Near(x.Displacements[0].Y,-0.0075,"Excel cached values with header unit");}finally{File.Delete(xlsx);}
  // Report content.
  r=BeamDeflection.Calculate(d,new PhysicalBeamInput{Name="B1",Members="1,2,3",LimitRatio=360,Vertical="Y",ServiceBasis=true,SupportsVerified=true});var all=r.Concat(BeamDeflection.Calculate(d,cant)).ToList();
  var summary=new BeamDeflectionSummary{GeometrySource="model.std",ResultSource="results.csv",GeometryUnit=d.GeometryUnitSource,DisplacementUnit=d.DisplacementUnitSource,Vertical="Y",ServiceBasis=true,SupportsVerified=true,Nodes=d.Nodes.Count,Members=d.Members.Count,Cases=d.Cases().ToList(),Criteria="L/360 - floor, immediate live load"};
  string plain=BeamDeflectionReport.Text(summary,all);Check(plain.Contains("9.67")&&plain.Contains("analysis nodes")&&plain.Contains("not constitute engineer approval"),"text report includes result and limitation");
  var report=BeamDeflectionReport.Create(summary,all);var titles=report.Sections.Select(s=>s.Title).ToList();Check(titles[0]=="Scope and method"&&titles.Contains("STAAD input data")&&titles.Contains("Deflection criteria")&&titles.Contains("Summary of checks")&&titles.Last()=="Limitations and review notes","numbered professional report sections: "+string.Join(" / ",titles));
  string html=report.Html();Check(html.Contains("<svg")&&html.Contains("9.67")&&!html.Contains("NaN")&&!html.Contains("Infinity"),"HTML report has figure and finite values");Check(report.Highlights.Any(h=>h.Key=="Governing δ/δallow"),"highlight of governing ratio");
  Check(BeamDeflectionReport.Svg(all[0]).Contains("polyline"),"deflected shape figure");
  Check(BeamDeflection.MemberIds("12-14, 20").SequenceEqual(new[]{12,13,14,20}),"member range list");
  Check(ProgramAccess.Ids.Contains(ProgramAccess.BeamDeflection)&&ProgramAccess.Names.Contains("Beam Deflection Check")&&ProgramAccess.ValidMask(256)&&ProgramAccess.All==503,"separate access program for Beam Deflection Check");
  Check(!ProgramAccess.Allows(ProgramAccess.WindDesign,ProgramAccess.BeamDeflection),"wind access does not grant deflection sheet");
  Console.WriteLine("PASS: "+checks+" beam deflection, STAAD table/STD/ANL/Excel import, units, cantilever, grouping and report checks");}
}
